-- A second kind of scenario (doc §4.12): "waves" — the planner as it was, which
-- every existing scenario stays — and "lease", a staggered lease built from a
-- client's reservations at a recent event, kept with the scenario.
ALTER TABLE "StaggerScenario" ADD COLUMN     "kind" TEXT NOT NULL DEFAULT 'waves',
ADD COLUMN     "reservations" JSONB;

